import csv, math, numpy as np, sys
from collections import Counter
from math import gcd, log
from functools import reduce
from scipy.optimize import minimize
rows=list(csv.DictReader(open('/scr/wurgaft/auto-psych/agent_trees/d82b8b9c1e886668/repo/_runs/cell_1/experiment2/model_loop/responses.csv')))
y=np.array([int(r['rating']) for r in rows])
def isprime(n): return n>1 and all(n%d for d in range(2,int(n**.5)+1))
R=range(1,101)
C={}
for k in range(3,13): C[f'm{k}']={x for x in R if x%k==0}
C['sq']={x*x for x in range(1,11)}; C['cu']={x**3 for x in range(1,5)}
for b in (2,3,4,5,10): C[f'p{b}']={b**i for i in range(1,8) if b**i<=100}
C['pr']={x for x in R if isprime(x)}
for d in range(10): C[f'e{d}']={x for x in R if x%10==d}
C['ev']={x for x in R if x%2==0}; C['od']={x for x in R if x%2}
S={k:log(100/len(v)) for k,v in C.items()}
def coinc(ex):
    n=len(ex)
    if n<2: return 0.
    b=0.
    if len({e%2 for e in ex})==1: b=max(b,(n-1)*log(2))
    if all(e%5==0 for e in ex): b=max(b,(n-1)*log(5))
    if len({e%10 for e in ex})==1: b=max(b,(n-1)*log(10))
    return b/(3*log(10))
F={k:[] for k in 'D U P Q M sp dh ph run co g reg greg'.split()}
for r in rows:
    ex=[int(x) for x in r['number_set'].split(',')][:4]; t=int(r['target']); n=len(ex)
    d=[0]*4;u=[0]*4;p=[0]*4;q=[0]*4;m=[0]*4
    for k,e in enumerate(ex):
        d[k]=abs(t-e)/10;u[k]=float(t%10!=e%10);p[k]=float(t%2!=e%2);q[k]=float(gcd(t,e)==1);m[k]=1
    F['D'].append(d);F['U'].append(u);F['P'].append(p);F['Q'].append(q);F['M'].append(m)
    if n>1:
        F['sp'].append((max(ex)-min(ex))/100); F['dh'].append((max(Counter(e%10 for e in ex).values())-1)/(n-1)); F['ph'].append((max(Counter(e%2 for e in ex).values())-1)/(n-1))
    else: F['sp'].append(.5);F['dh'].append(.5);F['ph'].append(.5)
    F['run'].append(float(n>=3 and len({e%10 for e in ex})==1))
    F['co'].append(coinc(ex))
    g=reduce(gcd,ex) if n>1 else 1
    # gcd rule: signed surprise, + if divisible, - if not
    F['g'].append(0. if g<3 else (log(g) if t%g==0 else -log(g)))
    shared=[c for c in C if all(e in C[c] for e in ex)] if n>1 else []
    hit=max([S[c] for c in shared if t in C[c]],default=0); miss=max([S[c] for c in shared if t not in C[c]],default=0)
    F['reg'].append(hit-miss)
    F['greg'].append(0.)
