        if 'run' in variant: cu=cu+ex[variant.index('run')]*F['run']
        if 'co' in variant: gain=np.exp(ex[variant.index('co')]*F['co'])[:,None]
        if 'g' in variant: z_extra=z_extra+ex[variant.index('g')]*F['g']
        if 'reg' in variant: z_extra=z_extra+ex[variant.index('reg')]*F['reg']
        if 'gsim' in variant:  # gcd rule inside similarity
            pass
        ls=gain*(-np.exp(lm-st*F['sp'])[:,None]*F['D']-np.exp(cu)[:,None]*F['U']-abs(cp)*F['ph'][:,None]*F['P']-abs(cf)*F['Q'])
        ls=np.where(F['M']>0,ls,-1e3); mx=ls.max(1); L=mx+np.log(np.exp(ls-mx[:,None]).sum(1))
        z=a+np.exp(lb)*L+z_extra
        pp=np.clip(1/(1+np.exp(-z)),1e-6,1-1e-6)
        return -(y*np.log(pp)+(1-y)*np.log(1-pp)).sum()
    return nll
def run(variant):
    nll=nll_fn(variant); best=None
    for s in range(3):
        x0=np.random.RandomState(s).normal(0,.3,8+len(variant))
        r=minimize(nll,x0,method='Nelder-Mead',options={'maxiter':8000,'maxfev':8000})
        r=minimize(nll,r.x,method='L-BFGS-B')
        if best is None or r.fun<best.fun: best=r
    print(variant,round(best.fun,2),best.x.round(2),flush=True)
for v in [[],['co'],['run'],['g'],['reg'],['co','g'],['run','g'],['co','reg']]:
    run(v)
